css:
.mcda-sim-container {
    padding: 24px;
    background: #f4f6f8;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
    color: #1c2733;
    max-width: 1280px;
    margin: 0 auto;
}

.mcda-sim-container h1,
.mcda-sim-container h3 {
    margin: 0;
}

.mcda-sim-header {
    background: linear-gradient(135deg, #0f2342 0%, #1a3a6c 100%);
    color: #ffffff;
    padding: 24px 28px;
    border-radius: 4px;
    margin-bottom: 24px;
    border-left: 4px solid #c9a961;
}
.mcda-sim-header-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 8px;
    gap: 12px;
    flex-wrap: wrap;
}
.mcda-sim-eyebrow {
    font-size: 0.7rem;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: #816d3d;
    font-weight: 600;
}
.mcda-sim-period-counter {
    font-size: 0.8rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: rgba(255,255,255,0.85);
    background: rgba(255,255,255,0.08);
    padding: 6px 14px;
    border-radius: 2px;
}
.mcda-sim-period-counter span {
    margin: 0 2px;
}
.mcda-sim-header h1 {
    font-size: 1.55rem;
    font-weight: 600;
    letter-spacing: 0.01em;
    margin: 4px 0 6px 0;
}
.mcda-sim-subtitle {
    font-size: 0.88rem;
    color: rgba(255,255,255,0.78);
    letter-spacing: 0.02em;
}

.mcda-sim-scenario {
    background: #ffffff;
    border: 1px solid #d8dde3;
    border-left: 4px solid #4a7c59;
    padding: 18px 22px;
    margin-bottom: 24px;
    border-radius: 4px;
}
.mcda-sim-scenario-tag {
    font-size: 0.7rem;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    color: #477755;
    font-weight: 700;
    margin-bottom: 6px;
}
.mcda-sim-scenario-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #2a3a4d;
}
.mcda-sim-scenario-text strong {
    display: block;
    color: #0f2342;
    font-size: 1.02rem;
    margin-bottom: 4px;
}

.mcda-sim-kpis {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 14px;
    margin-bottom: 24px;
}
.mcda-sim-kpi {
    background: #ffffff;
    border: 1px solid #d8dde3;
    border-top: 3px solid #1a3a6c;
    padding: 16px 18px;
    border-radius: 4px;
}
.mcda-sim-kpi-accent {
    border-top-color: #c9a961;
    background: #fffbf0;
}
.mcda-sim-kpi-label {
    font-size: 0.7rem;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: #5a6a7a;
    margin-bottom: 8px;
    font-weight: 600;
}
.mcda-sim-kpi-value {
    font-size: 2.1rem;
    font-weight: 700;
    color: #0f2342;
    line-height: 1.1;
    letter-spacing: -0.01em;
}
.mcda-sim-kpi-accent .mcda-sim-kpi-value {
    color: #846a28;
}

.mcda-sim-decisions {
    background: #ffffff;
    border: 1px solid #d8dde3;
    border-radius: 4px;
    padding: 22px 24px;
    margin-bottom: 24px;
}
.mcda-sim-decisions h3 {
    font-size: 0.95rem;
    color: #0f2342;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    font-weight: 700;
    margin-bottom: 14px;
    padding-bottom: 8px;
    border-bottom: 1px solid #e6ebf0;
}
.mcda-sim-weights-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 12px 16px;
    margin-bottom: 14px;
}
.mcda-sim-weight {
    display: flex;
    flex-direction: column;
    gap: 4px;
}
.mcda-sim-weight label {
    font-size: 0.75rem;
    color: #5a6a7a;
    font-weight: 600;
    margin: 0;
    letter-spacing: 0.02em;
}
.mcda-sim-weight input[type="number"] {
    background: #f8fafc;
    border: 1px solid #c8d1da;
    color: #1c2733;
    border-radius: 3px;
    padding: 7px 10px;
    font-size: 0.95rem;
    font-weight: 600;
    width: 100%;
    transition: border-color 0.2s ease, background 0.2s ease;
}
.mcda-sim-weight input[type="number"]:focus {
    border-color: #1a3a6c;
    background: #ffffff;
    outline: none;
    box-shadow: 0 0 0 3px rgba(26,58,108,0.12);
}

.mcda-sim-weights-sum {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 10px 14px;
    background: #f4f6f8;
    border: 1px solid #d8dde3;
    border-radius: 3px;
    font-size: 0.95rem;
    margin-bottom: 18px;
    font-weight: 600;
    width: fit-content;
}
.mcda-sim-weights-sum span:first-child {
    color: #5a6a7a;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    font-size: 0.75rem;
}
.mcda-sim-sum-ok {
    color: #2d6a4f;
    font-size: 1.15rem;
    font-weight: 700;
}
.mcda-sim-sum-bad {
    color: #b4322a;
    font-size: 1.15rem;
    font-weight: 700;
}
.mcda-sim-sum-target {
    color: #646f7b;
    font-size: 0.95rem;
}

.mcda-sim-site-row {
    display: grid;
    grid-template-columns: 1fr;
    gap: 8px;
    margin-bottom: 18px;
    max-width: 360px;
}
.mcda-sim-site-row h3 {
    margin-bottom: 4px;
}
.mcda-sim-site-row select {
    background: #f8fafc;
    border: 1px solid #c8d1da;
    color: #1c2733;
    border-radius: 3px;
    padding: 8px 12px;
    font-size: 0.95rem;
    font-weight: 600;
    width: 100%;
}
.mcda-sim-site-row select:focus {
    border-color: #1a3a6c;
    background: #ffffff;
    outline: none;
    box-shadow: 0 0 0 3px rgba(26,58,108,0.12);
}
.mcda-sim-site-row select option {
    background: #ffffff;
    color: #1c2733;
}

.mcda-sim-actions {
    display: flex;
    gap: 10px;
    align-items: center;
    flex-wrap: wrap;
}
.mcda-sim-container .btn {
    border-radius: 3px;
    font-weight: 600;
    letter-spacing: 0.04em;
    padding: 10px 20px;
    transition: background 0.2s ease, transform 0.1s ease;
    border: 1px solid transparent;
}
.mcda-sim-container .btn-primary {
    background: #0f2342;
    border-color: #0f2342;
    color: #ffffff;
}
.mcda-sim-container .btn-primary:hover {
    background: #1a3a6c;
    border-color: #1a3a6c;
    transform: translateY(-1px);
}
.mcda-sim-container .btn-outline-secondary {
    background: transparent;
    border: 1px solid #c8d1da;
    color: #5a6a7a;
}
.mcda-sim-container .btn-outline-secondary:hover {
    background: #eef2f6;
    border-color: #5a6a7a;
    color: #1c2733;
}

.mcda-sim-results {
    background: #ffffff;
    border: 1px solid #d8dde3;
    border-radius: 4px;
    padding: 22px 24px;
    margin-bottom: 24px;
}
.mcda-sim-results h3 {
    font-size: 0.95rem;
    color: #0f2342;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    font-weight: 700;
    margin-bottom: 14px;
    padding-bottom: 8px;
    border-bottom: 1px solid #e6ebf0;
}
.mcda-sim-ranking-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.92rem;
}
.mcda-sim-ranking-table th {
    text-align: left;
    padding: 10px 12px;
    background: #f4f6f8;
    color: #5a6a7a;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    font-size: 0.7rem;
    font-weight: 700;
    border-bottom: 1px solid #d8dde3;
}
.mcda-sim-ranking-table td {
    padding: 10px 12px;
    border-bottom: 1px solid #eef2f6;
    color: #1c2733;
}
.mcda-sim-ranking-table tr.mcda-sim-rank-1 td {
    background: rgba(74,124,89,0.08);
    font-weight: 700;
}
.mcda-sim-ranking-table tr.mcda-sim-rank-1 td:first-child {
    color: #2d6a4f;
}
.mcda-sim-ranking-note {
    margin-top: 10px;
    font-size: 0.82rem;
    color: #616e7b;
    font-style: italic;
}

.mcda-sim-history {
    background: #ffffff;
    border: 1px solid #d8dde3;
    border-radius: 4px;
    padding: 22px 24px;
    margin-bottom: 24px;
    overflow-x: auto;
}
.mcda-sim-history h3 {
    font-size: 0.95rem;
    color: #0f2342;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    font-weight: 700;
    margin-bottom: 14px;
    padding-bottom: 8px;
    border-bottom: 1px solid #e6ebf0;
}
.mcda-sim-history table {
    margin-bottom: 0;
}
.mcda-sim-history th {
    background: #f4f6f8;
    color: #5a6a7a;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    font-size: 0.72rem;
    font-weight: 700;
    border-bottom: 1px solid #d8dde3;
    padding: 10px 12px;
}
.mcda-sim-history td {
    padding: 10px 12px;
    border-bottom: 1px solid #eef2f6;
    font-size: 0.9rem;
}

.mcda-sim-chart {
    background: #ffffff;
    border: 1px solid #d8dde3;
    border-radius: 4px;
    padding: 22px 24px;
    margin-bottom: 24px;
}
.mcda-sim-chart h3 {
    font-size: 0.95rem;
    color: #0f2342;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    font-weight: 700;
    margin-bottom: 14px;
    padding-bottom: 8px;
    border-bottom: 1px solid #e6ebf0;
}
.mcda-sim-chart-wrap {
    height: 320px;
    position: relative;
}

@media (max-width: 768px) {
    .mcda-sim-container {
        padding: 14px;
    }
    .mcda-sim-header {
        padding: 18px 20px;
    }
    .mcda-sim-header h1 {
        font-size: 1.2rem;
    }
    .mcda-sim-kpi-value {
        font-size: 1.6rem;
    }
    .mcda-sim-weights-grid {
        grid-template-columns: repeat(2, 1fr);
    }
    .mcda-sim-chart-wrap {
        height: 240px;
    }
}

/* --- EQIL v1.1.0: focus visibility, reduced motion, mandate + end-state UI --- */
.mcda-sim-container :is(input, select, button, a):focus-visible {
    outline: 3px solid #1c4f7c;
    outline-offset: 2px;
    border-radius: 3px;
}
@media (prefers-reduced-motion: reduce) {
    .mcda-sim-container *,
    .mcda-sim-container *::before,
    .mcda-sim-container *::after {
        animation-duration: 0.001ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.001ms !important;
        scroll-behavior: auto !important;
    }
}
.mcda-sim-mandate {
    margin: 10px 0 14px;
    padding: 10px 12px;
    border: 1px solid #d7dee6;
    border-left: 4px solid #1c4f7c;
    border-radius: 4px;
    background: #ffffff;
}
.mcda-sim-mandate-title { font-weight: 700; color: #24313f; margin-bottom: 6px; font-size: 0.92rem; }
.mcda-sim-mandate-none { color: #4a5866; font-size: 0.9rem; }
.mcda-sim-mandate-list { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 6px 14px; }
.mcda-sim-mandate-list li { font-size: 0.88rem; }
.mcda-sim-mandate-ok { color: #2f6b43; }
.mcda-sim-mandate-ok::before { content: "\2713\00a0"; }
.mcda-sim-mandate-miss { color: #9c2a1f; font-weight: 600; }
.mcda-sim-mandate-miss::before { content: "\2715\00a0"; }
.mcda-sim-mandate-actual { color: #4a5866; }
.mcda-sim-discrim { margin-top: 6px; font-size: 0.86rem; }
.mcda-sim-discrim-ok { color: #4a5866; }
.mcda-sim-discrim-bad { color: #9c2a1f; font-weight: 600; }
.mcda-sim-complete {
    margin: 12px 0;
    padding: 12px 14px;
    border: 1px solid #2f6b43;
    border-radius: 4px;
    background: #f1f8f3;
    color: #24402d;
    font-weight: 600;
}

