        mirador:     { lcoe: 100, grid: 11,  community: 17,  biodiv: 67,  irrad: 100, tenure: 75,  water: 8,   workforce: 65,  regulatory: 80,  offtake: 100, financing: 80,  name: 'Mirador',     signature: 'Solar resource champion · grid-cost penalty' },
        llanos:      { lcoe: 92,  grid: 50,  community: 40,  biodiv: 50,  irrad: 91,  tenure: 100, water: 75,  workforce: 94,  regulatory: 100, offtake: 100, financing: 100, name: 'Llanos',      signature: 'Robust generalist · 40-year freehold' },
        costa_sur:   { lcoe: 87,  grid: 100, community: 11,  biodiv: 22,  irrad: 85,  tenure: 63,  water: 100, workforce: 100, regulatory: 70,  offtake: 100, financing: 100, name: 'Costa Sur',   signature: 'Engineering-friendly · biodiversity drag' },
        valle_norte: { lcoe: 96,  grid: 21,  community: 100, biodiv: 100, irrad: 94,  tenure: 38,  water: 38,  workforce: 76,  regulatory: 60,  offtake: 100, financing: 60,  name: 'Valle Norte', signature: 'License-led winner · 15-year lease cap' }
    };

    var WEIGHT_IDS = ['w_lcoe','w_grid','w_community','w_biodiv','w_irrad','w_tenure','w_water','w_workforce','w_regulatory','w_offtake','w_financing'];

    var SCORE_KEYS = ['lcoe','grid','community','biodiv','irrad','tenure','water','workforce','regulatory','offtake','financing'];

    // Each round brief prescribes an explicit weight emphasis. MANDATE encodes that
    // prose as machine-checkable floors and ceilings so the round is actually scored
    // against the stakeholder lens the brief describes. Round 1 and 6 are the
    // developer vector: no external mandate, the player defends their own vector.
    var ROUNDS = [
        { key: 'base',        nameKey: 'r_base_name',   descKey: 'r_base_desc',    mandateKey: 'm_base',   mandate: null },
        { key: 'financial',   nameKey: 'r_fin_name',    descKey: 'r_fin_desc',     mandateKey: 'm_fin',    mandate: { min: { w_lcoe: 25, w_grid: 15, w_financing: 15 } } },
        { key: 'license',     nameKey: 'r_lic_name',    descKey: 'r_lic_desc',     mandateKey: 'm_lic',    mandate: { min: { w_community: 25, w_biodiv: 12, w_regulatory: 12, w_tenure: 9 } } },
        { key: 'engineering', nameKey: 'r_eng_name',    descKey: 'r_eng_desc',     mandateKey: 'm_eng',    mandate: { min: { w_irrad: 18, w_grid: 18, w_workforce: 8 } } },
        { key: 'lender',      nameKey: 'r_lender_name', descKey: 'r_lender_desc',  mandateKey: 'm_lender', mandate: { min: { w_offtake: 18, w_tenure: 13, w_regulatory: 12, w_community: 12, w_biodiv: 10 }, max: { w_financing: 5 } } },
        { key: 'final',       nameKey: 'r_final_name',  descKey: 'r_final_desc',   mandateKey: 'm_final',  mandate: null }
    ];

    // Below this spread between the best and worst site the weight vector is not
    // discriminating between the alternatives, so the ranking it produces is an
    // artifact of tie-breaking rather than a defensible result.
    var DISCRIMINATION_FLOOR = 2.0;
    var TIE_EPS = 0.05;

    class HelioVerdeMCDAAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Helio Verde Renovables Site Selection MCDA';
            this.version = '1.1.0';
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    totalScore: 0,
                    defensibilityHistory: [],
                    robustnessHistory: [],
                    siteScoreHistory: { mirador: [], llanos: [], costa_sur: [], valle_norte: [] }
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    w_lcoe: 15, w_grid: 10, w_community: 15, w_biodiv: 8,
                    w_irrad: 10, w_tenure: 6, w_water: 5, w_workforce: 5,
                    w_regulatory: 8, w_offtake: 8, w_financing: 10,
                    site: 'llanos'
                };
            }
            var self = this;
            this._lastState = state;
            setTimeout(function() {
                self._syncControlsFromDecisions(state);
                self._updateBriefing(state);
                self._wireInputHandlers();
                self._renderRankingTable(state);
            }, 250);
        }

        // On resume the framework restores state.decisions but the DOM still holds the
        // authored defaults, so without this the player sees someone else's vector.
        _syncControlsFromDecisions(state) {
            var d = (state && state.decisions) || {};
            WEIGHT_IDS.forEach(function(id) {
                var el = document.getElementById(id);
                if (el && d[id] !== undefined && d[id] !== null) el.value = String(d[id]);
            });
            var siteEl = document.getElementById('siteSelect');
            if (siteEl && d.site) siteEl.value = d.site;
            this._updateWeightSum();
        }

        _currentRound(state) {
            var st = state || this._lastState || {};
            var idx = (st.currentPeriod || 1) - 1;
            return (idx >= 0 && idx < ROUNDS.length) ? ROUNDS[idx] : null;
        }

        // Share of the round mandate that the vector satisfies, with partial credit.
        // Returns 100 when the round carries no external mandate.
        _mandateScore(weights, round) {
            if (!round || !round.mandate) return 100;
            var parts = [];
            var mins = round.mandate.min || {};
            Object.keys(mins).forEach(function(id) {
                var need = mins[id];
                var got = weights[id] || 0;
                parts.push(need <= 0 ? 1 : Math.min(1, got / need));
            });
            var maxs = round.mandate.max || {};
            Object.keys(maxs).forEach(function(id) {
                var cap = maxs[id];
                var got = weights[id] || 0;
                if (got <= cap) { parts.push(1); return; }
                var over = got - cap;
                parts.push(Math.max(0, 1 - (over / 10)));
            });
            if (!parts.length) return 100;
            var sum = parts.reduce(function(a, b) { return a + b; }, 0);
            return Math.round((sum / parts.length) * 100);
        }

        _mandateRows(round, weights) {
            var rows = [];
            if (!round || !round.mandate) return rows;
            var mins = (round.mandate.min || {});
            Object.keys(mins).forEach(function(id) {
                rows.push({ id: id, op: 'min', target: mins[id], actual: weights[id] || 0, ok: (weights[id] || 0) >= mins[id] });
            });
            var maxs = (round.mandate.max || {});
            Object.keys(maxs).forEach(function(id) {
                rows.push({ id: id, op: 'max', target: maxs[id], actual: weights[id] || 0, ok: (weights[id] || 0) <= maxs[id] });
            });
            return rows;
        }

        _wireInputHandlers() {
            var self = this;
            var update = function() {
                self._updateWeightSum();
                self._renderRankingTable();
                self._renderMandate();
            };
            WEIGHT_IDS.forEach(function(id) {
                var el = document.getElementById(id);
                if (el) {
                    el.removeEventListener('input', update);
                    el.addEventListener('input', update);
                }
            });
            var siteEl = document.getElementById('siteSelect');
            if (siteEl) {
                siteEl.removeEventListener('change', update);
                siteEl.addEventListener('change', update);
            }
            this._updateWeightSum();
        }

        _updateWeightSum() {
            var sum = 0;
            WEIGHT_IDS.forEach(function(id) {
                var el = document.getElementById(id);
                if (el) sum += parseFloat(el.value) || 0;
            });
            var sumEl = document.getElementById('weightsSumDisplay');
            if (sumEl) {
                sumEl.textContent = sum.toFixed(0);
                sumEl.className = (Math.abs(sum - 100) < 0.5) ? 'mcda-sim-sum-ok' : 'mcda-sim-sum-bad';
            }
        }

        _readWeightsFromDOM() {
            var w = {};
            WEIGHT_IDS.forEach(function(id) {
                var el = document.getElementById(id);
                w[id] = el ? (parseFloat(el.value) || 0) : 0;
            });
            return w;
        }

        _scoreSites(weights) {
            var result = {};
            Object.keys(SITE_SCORES).forEach(function(siteKey) {
                var s = SITE_SCORES[siteKey];
                var sc = 0;
                for (var i = 0; i < SCORE_KEYS.length; i++) {
                    sc += s[SCORE_KEYS[i]] * (weights[WEIGHT_IDS[i]] || 0);
                }
                result[siteKey] = sc / 100;
            });
            return result;
        }

        _topSite(scores) {
            var best = null;
            var bestScore = -Infinity;
            Object.keys(scores).forEach(function(k) {
                if (scores[k] > bestScore) { bestScore = scores[k]; best = k; }
            });
            return best;
        }

        _spread(scores) {
            var vals = Object.keys(scores).map(function(k) { return scores[k]; });
            return Math.max.apply(null, vals) - Math.min.apply(null, vals);
        }

        // Rank with a tie tolerance so that sites separated by rounding noise share a
        // rank instead of being ordered by object-key accident.
        _rankOf(scores, siteKey) {
            var target = scores[siteKey];
            if (target === undefined) return null;
            var ahead = 0;
            Object.keys(scores).forEach(function(k) {
                if (scores[k] - target > TIE_EPS) ahead++;
            });
            return ahead + 1;
        }

        _t(key, fallback) {
            try {
                if (window.mySimulation && typeof window.mySimulation.t === 'function') {
                    var v = window.mySimulation.t(key);
                    if (v && v !== key) return v;
                }
            } catch (e) { /* translation layer not ready */ }
            return fallback !== undefined ? fallback : key;
        }

        _siteName(key) { return this._t('site_' + key, (SITE_SCORES[key] || {}).name || key); }

        _siteSignature(key) { return this._t('sig_' + key, (SITE_SCORES[key] || {}).signature || ''); }

        _renderRankingTable() {
            var self = this;
            var weights = this._readWeightsFromDOM();
            var sumW = WEIGHT_IDS.reduce(function(a, id) { return a + (weights[id] || 0); }, 0);
            var tbody = document.getElementById('rankingTableBody');
            if (!tbody) return;
            if (sumW <= 0) {
                tbody.innerHTML = '<tr><td colspan="4">' + self._t('ranking_empty', 'Set at least one criterion weight above zero to rank the sites.') + '</td></tr>';
                self._setDiscriminationNote(null);
                return;
            }
            var scores = this._scoreSites(weights);
            var sorted = Object.keys(scores).map(function(k) { return [k, scores[k]]; }).sort(function(a, b) { return b[1] - a[1]; });
            var html = '';
            for (var i = 0; i < sorted.length; i++) {
                var k = sorted[i][0];
                var v = sorted[i][1];
                var rank = self._rankOf(scores, k);
                var cls = (rank === 1) ? 'mcda-sim-rank-1' : '';
                html += '<tr class="' + cls + '"><td>' + rank + '</td><td>' + self._siteName(k) + '</td><td>' + v.toFixed(1) + '</td><td>' + self._siteSignature(k) + '</td></tr>';
            }
            tbody.innerHTML = html;
            self._setDiscriminationNote(this._spread(scores));
        }

        _setDiscriminationNote(spread) {
            var el = document.getElementById('discriminationNote');
            if (!el) return;
            if (spread === null || spread === undefined) { el.textContent = ''; el.className = 'mcda-sim-discrim'; return; }
            if (spread < DISCRIMINATION_FLOOR) {
                el.textContent = this._t('discrim_warn', 'This weight vector barely separates the sites — the ranking is not decision-grade.') + ' (' + spread.toFixed(1) + ')';
                el.className = 'mcda-sim-discrim mcda-sim-discrim-bad';
            } else {
                el.textContent = this._t('discrim_ok', 'Separation between best and worst site:') + ' ' + spread.toFixed(1);
                el.className = 'mcda-sim-discrim mcda-sim-discrim-ok';
            }
        }

        _renderMandate() {
            var box = document.getElementById('mandateBox');
            if (!box) return;
            var round = this._currentRound(this._lastState);
            var weights = this._readWeightsFromDOM();
            var rows = this._mandateRows(round, weights);
            if (!rows.length) {
                box.innerHTML = '<div class="mcda-sim-mandate-none">' + this._t('mandate_none', 'No external mandate this round — defend your own vector.') + '</div>';
                return;
            }
            var self = this;
            var html = '<div class="mcda-sim-mandate-title">' + this._t('mandate_title', 'Round mandate') + ' — ' + this._mandateScore(weights, round) + '%</div><ul class="mcda-sim-mandate-list">';
            rows.forEach(function(r) {
                var label = self._t(r.id + '_label', r.id);
                var op = (r.op === 'min') ? '&ge;' : '&le;';
                html += '<li class="' + (r.ok ? 'mcda-sim-mandate-ok' : 'mcda-sim-mandate-miss') + '">' + label + ' ' + op + ' ' + r.target + ' <span class="mcda-sim-mandate-actual">(' + r.actual + ')</span></li>';
            });
            html += '</ul>';
            box.innerHTML = html;
        }

        _robustness(weights, recommendedSite) {
            var totalChecks = 0;
            var passing = 0;
            var self = this;
            WEIGHT_IDS.forEach(function(id) {
                [-5, 5].forEach(function(delta) {
                    var w = {};
                    WEIGHT_IDS.forEach(function(k) { w[k] = weights[k]; });
                    w[id] = Math.max(0, w[id] + delta);
                    var total = WEIGHT_IDS.reduce(function(a, k) { return a + w[k]; }, 0);
                    if (total > 0) {
                        WEIGHT_IDS.forEach(function(k) { w[k] = (w[k] / total) * 100; });
                    }
                    var sc = self._scoreSites(w);
                    if (self._rankOf(sc, recommendedSite) <= 2) passing++;
                    totalChecks++;
                });
            });
            return totalChecks > 0 ? Math.round((passing / totalChecks) * 100) : 0;
        }

        _updateBriefing(state) {
            this._lastState = state;
            var idx = (state.currentPeriod || 1) - 1;
            var el = document.getElementById('scenarioText');
            var finished = idx >= ROUNDS.length;
            this._setRunOver(finished);
            if (finished) {
                if (el) el.innerHTML = '<strong>' + this._t('run_over_title', 'Run complete') + '</strong>' + this._t('run_over_desc', 'All six rounds are submitted. Review the round history and the debrief below.');
                return;
            }
            var round = ROUNDS[idx];
            if (el) {
                el.innerHTML = '<strong>' + this._t(round.nameKey, round.key) + '</strong>' + this._t(round.descKey, '');
            }
            this._renderMandate();
        }

        // Once the last round is submitted the decision panel and the submit row must
        // stop accepting input, otherwise the run ends on a live but inert form.
        _setRunOver(finished) {
            var over = finished;
            ['mcda-sim-decisions'].forEach(function(cls) {
                var nodes = document.getElementsByClassName ? document.getElementsByClassName(cls) : null;
                if (!nodes) return;
                for (var i = 0; i < nodes.length; i++) {
                    nodes[i].style.display = over ? 'none' : '';
                }
            });
            var row = document.getElementById('actionsRow');
            if (row) row.style.display = over ? 'none' : '';
            var btn = document.getElementById('nextPeriodBtn');
            if (btn) { btn.disabled = !!over; btn.style.display = over ? 'none' : ''; }
            var done = document.getElementById('runCompleteBanner');
            if (done) done.style.display = over ? '' : 'none';
        }

        validateDecisions(decisions) {
            var sum = 0;
            WEIGHT_IDS.forEach(function(id) {
                var el = document.getElementById(id);
                if (el) {
                    decisions[id] = parseFloat(el.value) || 0;
                    sum += decisions[id];
                }
            });
            var siteEl = document.getElementById('siteSelect');
            if (siteEl) decisions.site = siteEl.value;

            if (Math.abs(sum - 100) > 0.5) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('weights_warning'), 'warning'
                );
                return false;
            }
            if (!decisions.site || !SITE_SCORES[decisions.site]) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('site_warning'), 'warning'
                );
                return false;
            }
            this._lastState = window.mySimulation.state;
            return true;
        }

        // Thin wrapper: the round model lives in _computeRound so this method stays
        // short and its return statement is visible to static validators, current and
        // legacy alike. Keep this comment free of apostrophes, quotes and backticks:
        // the importer treats any of them as a string delimiter and desyncs its brace
        // counter, which produced the false empty-method and missing-return errors.
        calculateResults(state) {
            return this._computeRound(state);
        }

        _computeRound(state) {
            var d = state.decisions;
            var weights = {};
            WEIGHT_IDS.forEach(function(id) { weights[id] = d[id]; });

            var siteScores = this._scoreSites(weights);
            var topSite = this._topSite(siteScores);
            var userSite = d.site;

            var rank = this._rankOf(siteScores, userSite);
            var defensibility = (rank === null) ? 0 : Math.max(0, 100 - (rank - 1) * 30);

            // A vector that does not separate the alternatives cannot produce a
            // defensible recommendation, however the tie happens to break.
            var spread = this._spread(siteScores);
            var indecisive = spread < DISCRIMINATION_FLOOR;
            if (indecisive) defensibility = Math.min(defensibility, 50);

            var robustness = this._robustness(weights, userSite);

            // An 11-criterion MCDA answered on one or two criteria is not a
            // multi-criteria analysis; it has no robustness margin by construction.
            var effectiveCriteria = WEIGHT_IDS.filter(function(id) { return (weights[id] || 0) >= 3; }).length;
            var concentrated = effectiveCriteria < 5;
            if (concentrated) robustness = Math.min(robustness, 50);

            var round = this._currentRound(state);
            var mandate = this._mandateScore(weights, round);

            // The mandate gates the round rather than averaging into it: an analysis
            // is only as defensible as its compliance with the brief it answers.
            var analysis = (defensibility + robustness) / 2;
            var roundScore = Math.round(analysis * (mandate / 100));

            state.domainState.totalScore += roundScore;
            state.domainState.mandateHistory = state.domainState.mandateHistory || [];
            state.domainState.mandateHistory.push(mandate);
            state.domainState.defensibilityHistory.push(defensibility);
            state.domainState.robustnessHistory.push(robustness);
            Object.keys(siteScores).forEach(function(k) {
                state.domainState.siteScoreHistory[k].push(Math.round(siteScores[k] * 10) / 10);
            });
            // platform score: mean of the 0-100 round scores so far, the same _composite figure getPerformanceSummary reports as overallScore
            var playedRounds = state.domainState.defensibilityHistory.length || 1;
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, {
                overallScore: Math.max(0, Math.min(100, Math.round(state.domainState.totalScore / playedRounds)))
            });

            var self = this;
            var nextPeriod = state.currentPeriod + 1;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: nextPeriod, decisions: state.decisions });
                self._wireInputHandlers();
                self._renderRankingTable();
            }, 500);

            var aligned = (rank === 1);
            return {
                period: state.currentPeriod,
                defensibility: defensibility,
                robustness: robustness,
                mandate: mandate,
                roundKey: round ? round.key : null,
                indecisive: indecisive,
                concentrated: concentrated,
                effectiveCriteria: effectiveCriteria,
                spread: Math.round(spread * 10) / 10,
                roundScore: roundScore,
                topSite: this._siteName(topSite),
                userSite: this._siteName(userSite),
                userSiteKey: userSite,
                topSiteKey: topSite,
                topScore: Math.round(siteScores[topSite] * 10) / 10,
                userScore: Math.round(siteScores[userSite] * 10) / 10,
                match: aligned ? 'aligned' : 'mismatch',
                matchLabel: aligned ? this._t('match_aligned', 'Aligned') : this._t('match_mismatch', 'Mismatch')
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('totalScoreDisplay', 'domainState.totalScore', function(v) { return Math.round(v); });
            uiManager.bind('defensibilityDisplay', 'results.defensibility', function(v) { return v + '%'; });
            uiManager.bind('robustnessDisplay', 'results.robustness', function(v) { return v + '%'; });
            uiManager.bind('topSiteDisplay', 'results.topSite');
            uiManager.bind('mandateDisplay', 'results.mandate', function(v) { return v + '%'; });

            var self = this;
            setTimeout(function() {
                self._wireInputHandlers();
                self._renderRankingTable();
                self._renderMandate();
            }, 350);
        }

        getChartConfig() {
            return {
                scoresChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            { label: 'Mirador',     data: [], borderColor: '#e07a5f', backgroundColor: 'rgba(224,122,95,0.06)',  borderWidth: 2, fill: false, tension: 0.25 },
                            { label: 'Llanos',      data: [], borderColor: '#2d6a4f', backgroundColor: 'rgba(45,106,79,0.10)',   borderWidth: 3, fill: false, tension: 0.25 },
                            { label: 'Costa Sur',   data: [], borderColor: '#3d5a80', backgroundColor: 'rgba(61,90,128,0.06)',   borderWidth: 2, fill: false, tension: 0.25 },
                            { label: 'Valle Norte', data: [], borderColor: '#9c6644', backgroundColor: 'rgba(156,102,68,0.06)',  borderWidth: 2, fill: false, tension: 0.25 }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: 'bottom', labels: { color: '#1c2733', font: { size: 12 } } },
                            title: { display: false }
                        },
                        scales: {
                            x: { ticks: { color: '#5a6a7a' }, grid: { color: '#eef2f6' } },
                            y: { beginAtZero: false, suggestedMin: 35, suggestedMax: 95, ticks: { color: '#5a6a7a' }, grid: { color: '#eef2f6' } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var ds = (state && state.domainState) || {};
            var hh = ds.siteScoreHistory || {};
            var h = {
                mirador: hh.mirador || [],
                llanos: hh.llanos || [],
                costa_sur: hh.costa_sur || [],
                valle_norte: hh.valle_norte || []
            };
            var longest = Math.max(h.mirador.length, h.llanos.length, h.costa_sur.length, h.valle_norte.length);
            var labels = [];
            for (var i = 0; i < longest; i++) labels.push('R' + (i + 1));
            return {
                scoresChart: {
                    labels: labels,
                    datasets: [
                        { data: h.mirador },
                        { data: h.llanos },
                        { data: h.costa_sur },
                        { data: h.valle_norte }
                    ]
                }
            };
        }

        // Single place that turns per-round scores into the 0-100 figure the reporting
        // layer reads, so composite, overallScore, totalScore and score cannot drift.
        _composite(roundScores) {
            if (!roundScores || !roundScores.length) return 0;
            var sum = roundScores.reduce(function(a, b) { return a + b; }, 0);
            return Math.round(sum / roundScores.length);
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var self = this;
            var scores = history.map(function(r) { return (r.results && r.results.roundScore) || 0; });
            var cumulative = scores.reduce(function(s, p) { return s + p; }, 0);
            var avg = cumulative / scores.length;
            var overall = this._composite(scores);

            var performance = 'beginner';
            if (avg >= 65) performance = 'good';
            if (avg >= 85) performance = 'excellent';

            var llanosCount = history.filter(function(r) { return r.results && r.results.userSiteKey === 'llanos'; }).length;
            var alignedCount = history.filter(function(r) { return r.results && r.results.match === 'aligned'; }).length;
            var indecisiveCount = history.filter(function(r) { return r.results && r.results.indecisive; }).length;
            var mandates = history.map(function(r) { return (r.results && typeof r.results.mandate === 'number') ? r.results.mandate : 100; });
            var avgMandate = Math.round(mandates.reduce(function(s, p) { return s + p; }, 0) / mandates.length);
            var missedMandate = history.filter(function(r) { return r.results && typeof r.results.mandate === 'number' && r.results.mandate < 100; }).length;

            var insights = [];
            if (avg >= 80) insights.push(self._t('ins_def_high', 'Strong defensibility across rounds. Your weight vectors and recommendations were internally consistent.'));
            else if (avg >= 60) insights.push(self._t('ins_def_mid', 'Defensibility is acceptable. Tighten the alignment between weight vector and recommended site.'));
            else insights.push(self._t('ins_def_low', 'Several rounds had a mismatch between your weights and your pick. The IC will catch this before the memo goes upstairs.'));

            if (llanosCount >= 4) insights.push(self._t('ins_site_high', 'Strong recognition that Llanos is the robust answer in most weight regimes.'));
            else if (llanosCount >= 2) insights.push(self._t('ins_site_mid', 'Mixed pattern between Llanos and Valle Norte. The license-led scenario favours Valle Norte; in the rest Llanos wins or near-wins.'));
            else insights.push(self._t('ins_site_low', 'Reconsider the base case: under the developer weight vector Llanos tops the ranking and Valle Norte sits second.'));

            if (missedMandate > 0) insights.push(self._t('ins_mandate_miss', 'Rounds where you did not meet the stakeholder weight mandate:') + ' ' + missedMandate + ' / ' + history.length + '.');
            else insights.push(self._t('ins_mandate_ok', 'You met every stakeholder weight mandate. Each round was answered under the lens the room asked for.'));

            if (indecisiveCount > 0) insights.push(self._t('ins_indecisive', 'Rounds where the weight vector barely separated the sites, so the ranking was not decision-grade:') + ' ' + indecisiveCount + '.');

            var concentratedCount = history.filter(function(r) { return r.results && r.results.concentrated; }).length;
            if (concentratedCount > 0) insights.push(self._t('ins_concentrated', 'Rounds answered on fewer than five effective criteria, which is not a multi-criteria analysis:') + ' ' + concentratedCount + '.');
            insights.push(self._t('ins_aligned', 'Aligned-pick rounds:') + ' ' + alignedCount + ' / ' + history.length + '.');

            return {
                composite: overall,
                overallScore: overall,
                totalScore: overall,
                score: overall,
                cumulativeScore: cumulative,
                avgScore: overall,
                avgMandate: avgMandate,
                alignedRounds: alignedCount,
                indecisiveRounds: indecisiveCount,
                performance: performance,
                performanceKey: performance,
                performanceLabel: self._t('perf_' + performance, performance),
                insights: insights
            };
        }

        // Without this the debrief above is computed and then discarded by the
        // reporting layer, which is the single most common defect in this portfolio.
        formatCompletionMessage(history) {
            var s = this.getPerformanceSummary(history);
            if (!s || !s.insights) return '';
            var lines = [];
            lines.push(this._t('done_heading', 'IC readiness debrief'));
            lines.push(this._t('done_score', 'Overall score:') + ' ' + s.overallScore + '/100 (' + s.performanceLabel + ')');
            lines.push(this._t('done_mandate', 'Average mandate compliance:') + ' ' + s.avgMandate + '%');
            lines.push(this._t('done_aligned', 'Aligned-pick rounds:') + ' ' + s.alignedRounds + '/' + history.length);
            s.insights.forEach(function(i) { lines.push('- ' + i); });
            return lines.join('\n');
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.match === 'mismatch') return this._t('hint_mismatch');
            if (results.mandate !== undefined && results.mandate < 100) return this._t('hint_mandate');
            if (results.indecisive) return this._t('hint_indecisive');
            if (results.concentrated) return this._t('hint_concentrated');
            if (results.robustness < 50) return this._t('hint_low_robustness');
            if (results.defensibility < 60) return this._t('hint_low_defensibility');
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.userSite',      label: 'Pick',          i18nKey: 'col_pick' },
